import sys

def solve():
    input = sys.stdin.readline
    N = int(input())
    P = list(map(int, input().split()))

    bit = [0] * (N + 1)

    def add(i, x):
        while i <= N:
            bit[i] += x
            i += i & -i

    def sum_(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    ans = 0
    for i, x in enumerate(P, 1):
        cnt = sum_(N) - sum_(x)
        pos_sum = i * cnt - (sum_(N) - sum_(x))
        ans += pos_sum
        add(x, 1)

    print(ans)

if __name__ == "__main__":
